ailable": true}, {"name_ar": "بيبسي دايت", "name_en": "Pepsi Diet", "price_usd": 1, "desc_ar": "", "desc_en": "", "image_url": "", "is_available": true}, {"name_ar": "مياه صغيرة", "name_en": "Small Water", "price_usd": 0.5, "desc_ar": "", "desc_en": "", "image_url": "", "is_available": true}]}]}$tpl$::jsonb) on conflict (code) do update set name=excluded.name,data=excluded.data,updated_at=now();
